 * UI translations — Single source of truth cho TẤT CẢ chuỗi text cứng
 * (hard-coded) trên các trang HTML public của Hitour.
 *
 * Cấu trúc:
 *   return [
 *       '<locale_code>' => [
 *           '<key>' => '<text translated>',
 *           ...
 *       ],
 *       ...
 *   ];
 *
 * Locale code khớp với `config/language.php`:
 *   vi, en, zh-cn, zh-tw, ja, ko, es, fr, de, ru
 *
 * Helper sử dụng:
 *   {{ t('key') }}                                 // trả text theo locale hiện tại
 *   {{ t('key', ['name' => $item->display_name]) }} // có placeholder :name
 *
 * Nếu key không tồn tại trong locale hiện tại → fallback sang
 * `config('language.fallback_code', 'vi')`; nếu vẫn không có → trả lại
 * chính key (giúp dev phát hiện key thiếu).
 *
 * Quy ước placeholder: dùng dấu `:` đầu — vd `:name`, `:location`, `:year`.
 *
 * Khi thêm key mới: thêm ở TẤT CẢ 10 locale (vi → ru). Sau đó:
 *   php artisan config:clear && php artisan view:clear
 */

